import solution, copy
t={'db':{'host':'old','password':'secret'},'flags':[1,2],'gone':1}; p={'db':{'host':'new','password':None},'flags':[3],'gone':None}
t0=copy.deepcopy(t);p0=copy.deepcopy(p)
r=solution.patch_config(t,p)
assert r=={'db':{'host':'new'},'flags':[3]}
assert t==t0 and p==p0
r['flags'].append(9); assert p==p0
assert solution.patch_config({'x':5},{'x':{'enabled':True}})=={'x':{'enabled':True}}
assert solution.patch_config({'x':{'a':1}},{'x':{}})=={'x':{'a':1}}
assert solution.patch_config({}, {'absent':None})=={}
assert solution.patch_config({'x':[{'a':1}]},{})=={'x':[{'a':1}]}
r=solution.patch_config(t,{});r['db']['host']='changed';assert t==t0
assert solution.patch_config({}, {'x':{'gone':None}})=={'x':{}}
assert solution.patch_config({'x':7}, {'x':{'gone':None,'child':{'drop':None,'keep':2}}})=={'x':{'child':{'keep':2}}}
assert solution.patch_config({}, {'x':{'child':{'drop':None}}})=={'x':{'child':{}}}

